<script lang="ts" module>import type{Snippet}from'svelte';import type{ButtonProps}from'../button/button.svelte';export interface AskAiButtonProps extends Omit<ButtonProps,'variant'|'children'|'loading'>{label?:string;loading?:boolean;sparkle?:Snippet}</script>
<script lang="ts">import{Button}from'../button';let{label='Ask AI',loading=false,sparkle,disabled=false,...rest}:AskAiButtonProps=$props();function shine(node:HTMLElement){function move(e:PointerEvent){const r=node.getBoundingClientRect();node.style.setProperty('--rx-ai-x',`${e.clientX-r.left}px`);node.style.setProperty('--rx-ai-y',`${e.clientY-r.top}px`)}node.addEventListener('pointermove',move);return()=>{node.removeEventListener('pointermove',move);node.style.removeProperty('--rx-ai-x');node.style.removeProperty('--rx-ai-y')}} </script>
<span class="rx-ai" {@attach shine}><Button {...rest} {disabled} {loading} variant="transparent"><span class="rx-ai__sparkle" aria-hidden="true">{#if sparkle}{@render sparkle()}{:else}✦{/if}</span><span>{label}</span></Button></span>
<style>.rx-ai{position:relative;display:inline-flex;border-radius:var(--rx-radius);padding:1px;background:linear-gradient(120deg,rgb(var(--rx-ai-violet)),rgb(var(--rx-ai-cyan)),rgb(var(--rx-ai-pink)),rgb(var(--rx-ai-violet)));background-size:240% 240%;box-shadow:0 0 22px rgb(var(--rx-ai-violet)/.28);animation:rx-ai-mesh 4s linear infinite}.rx-ai::after{content:'';position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(circle at var(--rx-ai-x,50%) var(--rx-ai-y,50%),rgb(var(--rx-light)/.5),transparent 32%);mix-blend-mode:overlay}.rx-ai :global(.rx-button){color:rgb(var(--rx-light));background:linear-gradient(135deg,rgb(var(--rx-ai-violet)/.92),rgb(var(--rx-ai-pink)/.76));overflow:hidden}.rx-ai__sparkle{display:inline-flex;animation:rx-ai-sparkle 1.8s ease-in-out infinite}@keyframes rx-ai-mesh{to{background-position:240% 0}}@keyframes rx-ai-sparkle{50%{transform:rotate(18deg) scale(1.18)}}@media(prefers-reduced-motion:reduce){.rx-ai,.rx-ai__sparkle{animation:none}}</style>
